\label{prop:cons-envelope}
The function $p$ is continuously differentiable on $(0,1)$. For every $\theta\in(0,1)$, with
$\zeta_\theta=\theta\delta_0+(1-\theta)\mu_\theta$,
\begin{equation}\label{eq:cons-envelope-general}
 p'(\theta)=\mathcal{O}_\theta(0)-\int\mathcal{O}_\theta\,d\mu_\theta .
\end{equation}
In particular $p'=0$ on $(0,1)\cap(0,m_0]$, and for $m_0<\theta<1$
\begin{equation}\label{eq:cons-envelope}
 p'(\theta)=\mathcal{O}_\theta(0)-\mathcal{O}_\theta(q_\theta)
 =\frac12\int_0^{q_\theta}\xi''(s)\bigl\{\Gamma_\theta(s)-s\bigr\}\,ds>0 .
\end{equation}
Consequently $\Lambda$ is continuously differentiable on $(0,1)$, with
$\Lambda'(\theta)=p(\theta)+\theta p'(\theta)$.

\label{prop:ons-equilibrium}
Assume $\beta_2>0$, $\xi'''(0)=0$ and~\hyperref[hyp:H]{\textup{(H)}}. Then the following hold.
\begin{thmlist}
\item There is $\kappa\in(0,K_{\rm loc})$ with $[0,\kappa]\subset\operatorname{supp}\zeta_*$.
\item $\zeta_*(\{0\})=0$ and $U_*=a_0^{-1/2}$.
\item The distribution function $\alpha_*$ is continuously differentiable on $[0,\kappa)$.
 For $t\in[0,\kappa)$, with $U_t,V_t$ taken for $\zeta=\zeta_*$,
 \begin{equation}\label{eq:ons-quotient}
  \alpha_*(t)=\frac{\xi'''(t)\,\mathbb{E} U_t^2+\xi''(t)^2\,\mathbb{E} V_t^2}{2\,\xi''(t)^2\,\mathbb{E} U_t^3},
 \end{equation}
 and the slope at zero is
 \begin{equation}\label{eq:ons-slope}
  \rho_*:=\alpha_*'(0)=\frac{D_*}{2\sqrt{a_0}}>0 .
 \end{equation}
\end{thmlist}

\label{lem:cons-regular}
The following hold.
\begin{thmlist}
\item $\widehat{\Lambda}\ge0$ on $[0,1]$, $\widehat{\Lambda}=0$ on $[0,m_0]$, and $\widehat{\Lambda}>0$ on $(m_0,1]$.
\item If $m_0<\theta<1$, then $\zeta_\theta(\{0\})=\theta$.
\item $\overline{\Lambda}$ is affine on no nondegenerate subinterval of $[m_0,1]$.
\item If $m_0<1$, equivalently $\zeta_*\ne\delta_0$, then $f_{\mathrm{eq}}<f_1<\infty$, and for every
 $f\in(f_{\mathrm{eq}},f_1)$ the dual minimizer $\theta_f$ of Lemma~\ref{lem:cons-variational}(d) lies
 in $(m_0,1)$. If $m_0=1$, then $f_1=f_{\mathrm{eq}}$.
\end{thmlist}

\label{cor:cons-level}
Assume $\zeta_*\ne\delta_0$. Then $\Lambda'$ is continuous and strictly increasing on $(m_0,1)$,
with $\Lambda'(\theta)\tof_{\mathrm{eq}}$ as $\theta\downarrow m_0$ and $\Lambda'(\theta)\to f_1$ as
$\theta\uparrow1$. Hence $\Lambda'$ maps $(m_0,1)$ homeomorphically onto $(f_{\mathrm{eq}},f_1)$, and
every $f\in(f_{\mathrm{eq}},f_1)$ has $\theta_f=(\Lambda')^{-1}(f)$ and
\begin{equation}\label{eq:cons-level}
 f=\Lambda'(\theta_f)=P_{\zeta_f}+\theta_f\bigl\{\mathcal{O}_f(0)-\mathcal{O}_f(q_f)\bigr\}.
\end{equation}

\label{lem:plat-law}
Let $0\le s<t\le1$ with $\zeta((s,t))=0$, and put $m=\zeta([0,s])$. Conditionally on
$X_s=x$, the law of $X_t$ has the density
$y\mapsto\exp\{m[\Phi_\zeta(t,y)-\Phi_\zeta(s,x)]\}\,\varphi_{\xi'(t)-\xi'(s)}(y-x)$,
where $\varphi_T$ is the $\mathcal N(0,T)$ density. In particular, if $0<q\le1$,
$\zeta((0,q))=0$ and $m=\zeta(\{0\})$, then
\begin{equation}\label{eq:plat-law}
 \frac{d\operatorname{Law}(X_q)}{d\mathcal N(0,\xi'(q))}(y)
 =\exp\bigl\{m\bigl[\Phi_\zeta(q,y)-\Phi_\zeta(0,0)\bigr]\bigr\} .
\end{equation}

\label{lem:plat-ito}
Let $\zeta\in\mathcal{P}([0,1])$ and $\Gamma=\Gamma_\zeta$.
\begin{thmlist}
\item $\Gamma\in C^1[0,1]$, $\Gamma(0)=0$ and
 $\Gamma'(t)=a(t)\mathbb{E} U_t^2$.
\item For $t\in[0,1)$ the right derivative of $\Gamma'$ at $t$ exists and equals
 $a'(t)\mathbb{E} U_t^2+a(t)^2\mathbb{E}\bigl(V_t^2-2\zeta([0,t])\,U_t^3\bigr)$; for $t\in(0,1]$ the left derivative exists and is given by the same expression with
 $\zeta([0,t))$ in place of $\zeta([0,t])$. Writing $\Gamma''(t+)$ and $\Gamma''(t-)$ for
 these one-sided derivatives,
 \begin{gather}
  \Gamma''(0+)=\xi'''(0)\,\Phi_{\zeta,xx}(0,0)^2
  -2a_0^2\,\zeta(\{0\})\,\Phi_{\zeta,xx}(0,0)^3,\label{eq:plat-zero}\\
  \Gamma''(t-)-\Gamma''(t+)=2a(t)^2\,\zeta(\{t\})\,\mathbb{E} U_t^3\qquad(0<t<1).\label{eq:plat-jump}
 \end{gather}
\item On an open plateau of height $m$, $\Gamma$ is three
 times continuously differentiable, and
 \begin{align}
  \Gamma''&=a'\mathbb{E} U_t^2+a^2\mathbb{E}\bigl(V_t^2-2mU_t^3\bigr),\label{eq:plat-second}\\
  \Gamma'''&=a''\mathbb{E} U_t^2+3aa'\mathbb{E}\bigl(V_t^2-2mU_t^3\bigr)
  +a^3\mathbb{E}\bigl(W_t^2-12mU_tV_t^2+6m^2U_t^4\bigr),\label{eq:plat-third}
 \end{align}
 where $a$, $a'$, $a''$ are evaluated at $t$.
\end{thmlist}

\label{lem:plat-kernel}
Let $q>0$, and let $g\in C^1[0,q]$ be three times continuously differentiable on $(0,q)$
with $g'''$ bounded and $g(0)=g(q)=g'(q)=0$. Then $g''$ extends continuously to $[0,q]$; write $g''(0+)$ and $g''(q-)$ for its end
values. Moreover
\begin{equation}\label{eq:plat-onset-identity}
 0=\int_0^qt\,g''(t)\,dt=\frac{q^2}2\,g''(0+)+\frac12\int_0^q(q^2-s^2)\,g'''(s)\,ds,
\end{equation}
and
\begin{equation}\label{eq:plat-kernel}
 \int_0^qg(s)\,ds=\int_0^qJ(u)\,g'''(u)\,du,\qquad J(u)=\frac{u^2(q-u)}6\ge0,\qquad
 \int_0^qJ(u)\,du=\frac{q^4}{72}.
\end{equation}

\label{cor:plat-first-plateau}
Let $\zeta\in\mathcal{P}([0,1])$ and $0<q<s<1$ be such that $\zeta((0,q))=0$ and
$\Gamma_\zeta(t)=t$ for $q\le t\le s$. Put $m=\zeta(\{0\})$ and, for $D\in\mathbb{R}$,
$\varepsilon=\sup_{0<t<q}|\Gamma_\zeta'''(t)-D|$. Then $\varepsilon<\infty$, and:
\begin{thmlist}
\item $\bigl|\xi'''(0)\,\Phi_{\zeta,xx}(0,0)^2-2a_0^2m\,\Phi_{\zeta,xx}(0,0)^3
 +\frac23Dq\bigr|\le\frac23\,\varepsilon q$;
\item $\bigl|2a(q)^2\,\zeta(\{q\})\,\mathbb{E} U_q^3-\frac13Dq\bigr|\le\frac53\,\varepsilon q$;
\item $\bigl|\Gamma_\zeta(t)-t-\frac D6t(q-t)^2\bigr|\le\frac56\,\varepsilon q(q-t)^2$ for
 $0\le t\le q$, and
 $\bigl|\int_0^q(\Gamma_\zeta(t)-t)\,dt-\frac{Dq^4}{72}\bigr|\le\frac{\varepsilon q^4}{72}$.
\end{thmlist}
If $\xi'''(0)=0$ and $D=D_*$, then moreover
$\varepsilon\le C_\Psi(q^{1/2}+W_1(\zeta,\zeta_*))+6m^2a_0^3U_*^4$, with $C_\Psi$ as
in Lemma~\ref{lem:plat-local-plateau}.

\label{lem:fld-diffusion}
Let $\zeta$ be a probability measure on $[0,1]$ and $h\in\mathbb{R}$.
\begin{thmlist}
\item Equation~\eqref{eq:fld-sde} has a pathwise unique continuous solution, and $X^{\zeta,-h}$
 has the law of $-X^{\zeta,h}$. Consequently $\Gamma_{\zeta,-h}=\Gamma_{\zeta,h}$,
 $\mathbb{E}\Phi_{\zeta,xx}(t,X^{\zeta,-h}_t)^2=\mathbb{E}\Phi_{\zeta,xx}(t,X^{\zeta,h}_t)^2$,
 $P^{-h}_\zeta=P^h_\zeta$ and $\zeta_{-h}=\zeta_h$.
\item If $0<q\le1$ and $\zeta([0,q))=0$, then $X^{\zeta,h}_q\sim\mathcal N(h,\xi'(q))$ and
 \begin{equation}\label{eq:fld-heat}
  \Phi_\zeta(t,x)=\mathbb{E}\Phi_\zeta\bigl(q,x+\sqrt{\xi'(q)-\xi'(t)}\,Z\bigr)\qquad(0\le t\le q).
 \end{equation}
\item The measure $\zeta_h$ gives full mass to the set of minimizers of $\mathcal{O}_{\zeta_h,h}$ over
 $[0,1]$, and every $q\in\operatorname{supp}\zeta_h\cap(0,1)$ satisfies
 \begin{equation}\label{eq:fld-sc}
  \Gamma_{\zeta_h,h}(q)=q,\qquad \xi''(q)\,\mathbb{E}\Phi_{\zeta_h,xx}(q,X^{\zeta_h,h}_q)^2\le1 .
 \end{equation}
 If $h\ne0$, then $0\notin\operatorname{supp}\zeta_h$.
\end{thmlist}

\label{lem:fld-ito}
Let $\zeta$ be a probability measure on $[0,1]$, $h\in\mathbb{R}$, $X=X^{\zeta,h}$, $\Gamma=\Gamma_{\zeta,h}$
and $\alpha=\alpha_\zeta$.
\begin{thmlist}
\item For every polynomial $\mathsf P$ and every $j\ge1$, the function
 $t\mapsto\mathbb{E}\,\mathsf P(\partial_x\Phi_\zeta,\dots,\partial_x^j\Phi_\zeta)(t,X_t)$ is continuous
 on $[0,1]$.
\item $\Gamma\in C^1[0,1]$ and $\Gamma'(t)=a(t)\mathbb{E} U_t^2$.
\item For every $t\in[0,1)$, $\Gamma'$ has the right derivative
 $a'(t)\mathbb{E} U_t^2+a(t)^2\mathbb{E}\bigl(V_t^2-2\alpha(t)U_t^3\bigr)$.
\item If $\alpha=m$ on an open interval $I\subset(0,1)$, then $\Gamma\in C^3(I)$ and, on $I$,
 \begin{align}
  \Gamma''&=a'\mathbb{E} U^2+a^2\mathbb{E}\bigl(V^2-2mU^3\bigr),\label{eq:fld-second}\\
  \Gamma'''&=a''\mathbb{E} U^2+3aa'\mathbb{E}\bigl(V^2-2mU^3\bigr)
   +a^3\mathbb{E}\bigl(W^2-12mUV^2+6m^2U^4\bigr).\label{eq:fld-third}
 \end{align}
\end{thmlist}

\label{lem:fld-structure}
Assume \hyperref[hyp:H]{\textup{(H)}}. Then part~(a) of Theorem~\ref{thm:field} holds with $h_1\le1$ and
$\xi'(\kappa_1)\le1$, and $q_{\min}(h)\to0$ as $h\to0$.

\label{lem:fld-taylor}
Let $v\in C^\infty(\mathbb{R})$ be odd with $|v|\le1$ and $\|v^{(j)}\|_\infty\le C$ for $1\le j\le8$. Put
$c_1=v'(0)$, $c_3=v'''(0)$ and $c_5=v^{(5)}(0)$. Let $0<h\le1$, $0<\sigma\le1$ and $X=h+\sigma Z$
with $Z$ standard Gaussian. Then, with implied constants depending only on $C$,
\begin{align}
 \mathbb{E} v(X)&=h\Bigl(c_1+\frac{c_3}2\sigma^2+\frac{c_5}8\sigma^4+O(h^2+\sigma^6)\Bigr),
 \label{eq:fld-t1}\\
 \mathbb{E} v'(X)^2&=c_1^2+c_1c_3\sigma^2+\Bigl(\frac34c_3^2+\frac14c_1c_5\Bigr)\sigma^4
  +O(h^2+\sigma^6),\label{eq:fld-t2}\\
 \mathbb{E} v(X)^2-\sigma^2\mathbb{E} v'(X)^2&=c_1^2h^2-\frac{c_3^2}3\,\sigma^6
  +O(h^2\sigma^2+h^4+\sigma^8).\label{eq:fld-t3}
\end{align}

\label{cor:fld-examples}
\begin{thmlist}
\item For $\xi(t)=\beta^2t^2/2$ with $\beta>1$, the hypotheses of Theorem~\ref{thm:local}, and
 hence those of Theorem~\ref{thm:field}, hold.
\item Let $\varepsilon_*$ be as in Theorem~\ref{thm:nearcrit}(a). The hypotheses of
 Theorem~\ref{thm:field} hold for every $\xi\in\mathcal{K}(\varepsilon_*)$. This class contains
 $\xi(t)=bt^2+et^4$ whenever $b>\frac12$, $e\ge0$ and $24(b-\frac12+e)<\varepsilon_*$, and
 $\xi(t)=\beta^2t^2/2$ whenever $1<\beta^2<1+\varepsilon_*$.
\end{thmlist}

\label{prop:atom-slope}
The function $\Sigma$ is finite and concave on $\mathbb{R}$, and $\Sigma=0$ on $(-\infty,f_{\mathrm{eq}}]$. For
every $\delta>0$,
\begin{equation}\label{eq:atom-exact}
 \Sigma(f_{\mathrm{eq}}+\delta)=-m_0\delta-S(\delta),\qquad
 S(\delta):=\sup_{0\le s\le1-m_0}\bigl\{s\delta-\widehat{\Lambda}(m_0+s)\bigr\},
\end{equation}
and $0\le S(\delta)=o(\delta)$ as $\delta\downarrow0$. Consequently
\begin{equation}\label{eq:atom-slope}
 \Sigma(f_{\mathrm{eq}}+\delta)=-\zeta_*(\{0\})\,\delta+o(\delta),\qquad
 \Sigma'_+(f_{\mathrm{eq}})=-\zeta_*(\{0\}),
\end{equation}
and $|\Sigma(f_{\mathrm{eq}}+\delta)|=o(\delta)$ if and only if $\zeta_*(\{0\})=0$. If $m_0<1$, then
$\theta_f\to m_0$ and $\zeta_f\Rightarrow\zeta_*$ weakly as $f\downarrowf_{\mathrm{eq}}$.

\label{prop:atom-atom}
\leavevmode
\begin{thmlist}
\item If zero is an isolated point of $\operatorname{supp}\zeta_*$, then $m_0>0$. This is the case whenever
 $\xi''(0)<1$, in particular whenever $\beta_2=0$.
\item If zero is an accumulation point of $\operatorname{supp}\zeta_*$, then $\xi''(0)U_*^2=1$, so
 $\xi''(0)\ge1$, and
 \begin{equation}\label{eq:atom-formula}
  \zeta_*(\{0\})=\frac{\xi'''(0)}{2\xi''(0)^{3/2}}=\frac{3\beta_3^2}{(2\beta_2^2)^{3/2}} .
 \end{equation}
\item $\zeta_*(\{0\})=0$ if and only if $\beta_3=0$ and zero is an accumulation point of
 $\operatorname{supp}\zeta_*$.
\end{thmlist}

\label{lem:nc-positive-third}
There are $K_P\in(0,1)$, $\varepsilon_P\in(0,\frac14]$ and a weak neighbourhood
$\mathcal W_P$ of $\delta_0$ in $\mathcal{P}([0,1])$ such that
\[
 \Psi^\xi_\zeta(t,m)\ge2\qquad(0\le t\le K_P,\ 0\le m\le1)
\]
for every covariance $\xi$ with $\|\xi-\xi_c\|_{C^4[0,1]}<\varepsilon_P$ and every
$\zeta\in\mathcal W_P$. For such $\xi$ and $\zeta$,
\begin{equation}\label{eq:nc-positive-third}
 \Gamma'''_\zeta\ge2\quad\text{on every open plateau of $\zeta$ contained in $(0,K_P)$.}
\end{equation}

\label{lem:nc-confinement}
\begin{thmlist}
\item For every weak neighbourhood $\mathcal W$ of $\delta_0$ there is $\varepsilon>0$ such
 that $\zeta_{\xi,\theta}\in\mathcal W$ for every covariance $\xi$ with
 $\|\xi-\xi_c\|_{C^4[0,1]}<\varepsilon$ and every $\theta\in[0,1]$.
\item For every $K\in(0,1)$ there are $\varepsilon>0$ and a weak neighbourhood
 $\mathcal W_K$ of $\delta_0$ such that
 \begin{equation}\label{eq:nc-confinement}
  \Gamma^\xi_\zeta(t)<t\qquad(K\le t\le1)
 \end{equation}
 for every covariance $\xi$ with $\|\xi-\xi_c\|_{C^4[0,1]}<\varepsilon$ and every
 $\zeta\in\mathcal W_K$. For such $\xi$ and $\zeta$, no point of $[K,1]$ minimizes $\mathcal{O}_\zeta$
 over $[0,1]$ or over $(0,1]$; in particular no point of $[K,1]$ is a contact of~$\zeta$.
\end{thmlist}

\label{lem:nc-gap}
Let $\|\xi-\xi_c\|_{C^4[0,1]}<\varepsilon_1$ and $\zeta\in\mathcal W$.
\begin{thmlist}
\item If $0<u<v<K$ are local minimum points of $\mathcal{O}_\zeta$, then $\zeta((u,v))>0$.
\item If $\zeta=\zeta_*$ is the unconstrained minimizer of $P^\xi$ and
 $v\in\operatorname{supp}\zeta_*\cap(0,K)$, then $\zeta_*((0,v))>0$.
\end{thmlist}

\label{prop:nc-support}
Let $\xi(t)=\sum_{p\ge2}\beta_p^2t^p$ have radius of convergence greater than one, with
$\xi''(0)>1$ and $\|\xi-\xi_c\|_{C^4[0,1]}<\varepsilon_1$.
\begin{thmlist}
\item $\xi''(t)>1-\|\xi-\xi_c\|_{C^4[0,1]}$ for $t\in[-1,1]$; in particular $\xi$ is strictly
 convex on $[-1,1]$.
\item $\operatorname{supp}\zeta_*=[0,v_*]$ for some $v_*\in(0,K)$. In particular zero is an accumulation
 point of $\operatorname{supp}\zeta_*$.
\end{thmlist}

\label{prop:nc-class}
Every $\xi\in\mathcal{K}(\varepsilon_1)$ has the following properties.
\begin{thmlist}
\item $\xi''(t)>1-\varepsilon_1$ for $t\in[-1,1]$; in particular $\xi$ is strictly convex on
 $[-1,1]$.
\item $\operatorname{supp}\zeta_*=[0,v_*]$ for some $v_*\in(0,K)$. In particular \hyperref[hyp:H]{\textup{(H)}}\ holds, and
 Theorem~\ref{thm:local} applies to $\xi$.
\item $D_*\ge2$.
\item There is $\theta_0\in(0,1)$ such that, for $0<\theta<\theta_0$,
 $\operatorname{supp}\zeta_\theta=\{0\}\cup[q_\theta,v_\theta]$ with $0<q_\theta<v_\theta<K$, and the first
 positive contact $q_\theta$ is marginal. As $\theta\downarrow0$,
 \begin{equation}\label{eq:nc-onset}
  \frac{q_\theta}\theta\longrightarrow\frac{3\sqrta_0}{D_*},\qquad
  \frac{\zeta_\theta(\{q_\theta\})}\theta\longrightarrow\frac12 .
 \end{equation}
\end{thmlist}

\label{prop:atom-odd-onset}
Let $\xi\in\mathcal{K}_3(\varepsilon_3)$. Then $D_*\ge2$, and as $\theta\downarrow m_0$:
\begin{thmlist}
\item $q_\theta\to0$ and
 $\bar U_\theta:=\Phi_{\zeta_\theta,xx}(0,0)=a_0^{-1/2}\bigl(1+\tfrac{D_*}{12}q_\theta^2
 +o(q_\theta^2)\bigr)$;
\item the first contact and its atom satisfy
 \begin{equation}\label{eq:atom-odd-onset}
  \frac{q_\theta}{\theta-m_0}\longrightarrow\frac{3\sqrt{a_0}}{D_*},\qquad
  \frac{\zeta_\theta(\{q_\theta\})}{\theta-m_0}\longrightarrow\frac12 ;
 \end{equation}
\item with $c$ as in \eqref{eq:atom-odd-D},
 \begin{gather}
  p'(\theta)=5c(\theta-m_0)^4(1+o(1)),\qquad
  p(\theta)-f_{\mathrm{eq}}=c(\theta-m_0)^5(1+o(1)),\label{eq:atom-odd-p}\\
  \Lambda(\theta)-\thetaf_{\mathrm{eq}}=m_0c(\theta-m_0)^5(1+o(1)),\qquad
  \Lambda'(\theta)-f_{\mathrm{eq}}=5m_0c(\theta-m_0)^4(1+o(1)).\label{eq:atom-odd-Lambda}
 \end{gather}
\end{thmlist}

\label{prop:atom-odd-rate}
Let $\xi\in\mathcal{K}_3(\varepsilon_3)$. As $\delta\downarrow0$,
\begin{equation}\label{eq:atom-odd-rate}
 \Sigma(f_{\mathrm{eq}}+\delta)=-m_0\delta-\frac45\,(5m_0c)^{-1/4}\,\delta^{5/4}\,(1+o(1)),
 \qquad
 \frac45\,(5m_0c)^{-1/4}=\frac{8}{5\sqrt3}\Bigl(\frac{D_*}{a_0}\Bigr)^{3/4}m_0^{-1/4}.
\end{equation}
At the level $f=f_{\mathrm{eq}}+\delta$, $\theta_f-m_0=(\delta/(5m_0c))^{1/4}(1+o(1))$,
$q_f=\frac{3\sqrt{a_0}}{D_*}(\theta_f-m_0)(1+o(1))$ and
$\zeta_f(\{q_f\})=\frac12(\theta_f-m_0)(1+o(1))$.

\label{prop:nc-above-contact}
For every $\xi\in\mathcal{K}(\varepsilon_*)$, as $\theta\downarrow0$:
\begin{thmlist}
\item $L_\theta=O(\theta^5)$;
\item $|v_\theta-v_*|=O(\theta^5)$ and
 $\sup\{|\Delta_\theta(t)|:t\in[q_\theta,v_-)\cup[v_+,1]\}=O(\theta^5)$; in particular
 $x_\theta=\zeta_*([0,q_\theta])+O(\theta^5)$;
\item $\sup_{x_\theta<x<1}|Q_\theta(x)-Q_*(x)|=O(\theta^5)$;
\item $q_\theta=\dfrac{3\sqrta_0}{D_*}\,\theta\,(1+O(\theta))$,
 $\zeta_\theta(\{q_\theta\})=\dfrac\theta2\,(1+O(\theta))$, and
 \[
  W_1(\zeta_\theta,\zeta_*)=\frac{5\sqrta_0}{4D_*}\,\theta^2\,(1+O(\theta)).
 \]
\end{thmlist}
The implied constants depend on $\xi$.

\label{lem:plat-jets}
\begin{thmlist}
\item For a fixed covariance there are constants $C_k$, depending only on $\xi$ and $k$,
 such that for all $\zeta,\nu\in\mathcal{P}([0,1])$
 \begin{equation}\label{eq:plat-jet-stability}
  \|\partial_x^k(\Phi_\zeta-\Phi_\nu)\|_\infty\le C_k\|a\|_\inftyW_1(\zeta,\nu)
  \qquad(k\ge1).
 \end{equation}
\item The constants $B_k$ in \eqref{eq:plat-bounds} can be chosen uniformly over
 $\mathfrak F$. For every $k\ge0$ there is $C_k'$, depending only on $k$ and
 $\mathfrak F$, such that
 \begin{equation}\label{eq:plat-jet-general}
  \|\partial_x^k(u-\tilde u)\|_\infty
  \le C_k'\bigl(\|a-\tilde a\|_{L^1[0,1]}+\|a\alpha-\tilde a\tilde\alpha\|_{L^1[0,1]}\bigr).
 \end{equation}
\item For every $k\ge1$ there is $L_k$, depending only on $\xi$ and $k$, such that for
 every $\zeta$ and all $s,t\in[0,1]$
 \begin{equation}\label{eq:plat-time-lip}
  \sup_{x\in\mathbb{R}}|\partial_x^k\Phi_\zeta(t,x)-\partial_x^k\Phi_\zeta(s,x)|\le L_k|t-s| .
 \end{equation}
\item For every $\zeta$ and $t\in[0,1]$,
 \begin{equation}\label{eq:plat-small-time}
  \mathbb{E} X_t^2\le2\|a\|_\infty t+2\|a\|_\infty^2t^2 .
 \end{equation}
\item For all $\zeta,\nu\in\mathcal{P}([0,1])$, $t\in[0,1]$ and $k\ge1$,
 \begin{equation}\label{eq:plat-origin}
  \mathbb{E}\bigl|\partial_x^k\Phi_\zeta(t,X^\zeta_t)-\partial_x^k\Phi_\nu(0,0)\bigr|
  \le B_{k+1}\bigl(2\|a\|_\infty t+2\|a\|_\infty^2t^2\bigr)^{1/2}+L_kt
  +C_k\|a\|_\inftyW_1(\zeta,\nu).
 \end{equation}
\end{thmlist}

\label{lem:cons-gartner-ellis}
Assume \hyperref[hyp:FM]{\textup{(FM)}}. Then for every $f\in(f_{\mathrm{eq}},f_1)$,
\begin{equation}\label{eq:cons-ldp}
 \lim_{N\to\infty}\frac1N\log\mathbb{P}\bigl(N^{-1}\logZ_N\ge f\bigr)=\Sigma(f).
\end{equation}
The interval $(f_{\mathrm{eq}},f_1)$ is nonempty if and only if $\zeta_*\ne\delta_0$.

\label{lem:cons-original-sk}
Let $\xi(t)=\beta^2t^2/2$ with $\beta>0$, and let
$F_{N,\beta}=\log\sum_{\sigma\in\{-1,1\}^N}\exp\bigl(\beta N^{-1/2}\sum_{i<j}g_{ij}\sigma_i\sigma_j\bigr)$
with independent standard Gaussian $g_{ij}$. For all $f\in\mathbb{R}$, $\eta>0$ and $N\ge1$,
\begin{equation}\label{eq:cons-sk-sandwich}
\begin{aligned}
 \mathbb{P}\bigl(N^{-1}F_{N,\beta}-\log2\ge f\bigr)
 &\le\mathbb{P}\bigl(N^{-1}\logZ_N\ge f-\eta\bigr)+e^{-\eta^2N^2/\beta^2},\\
 \mathbb{P}\bigl(N^{-1}\logZ_N\ge f+\eta\bigr)
 &\le\mathbb{P}\bigl(N^{-1}F_{N,\beta}-\log2\ge f\bigr)+e^{-\eta^2N^2/\beta^2}.
\end{aligned}
\end{equation}
Consequently, if $\lim_NN^{-1}\log\mathbb{P}(N^{-1}\logZ_N\ge f)=\Sigma(f)$ for every $f$ in an open
interval $I$, then $\lim_NN^{-1}\log\mathbb{P}(N^{-1}F_{N,\beta}-\log2\ge f)=\Sigma(f)$ for every $f\in I$.

\label{lem:A-fm-sk}
Let $\xi(t)=\beta^2t^2/2$ with $\beta>0$. Then \hyperref[hyp:FM]{\textup{(FM)}}\ holds: for every $\theta\in(0,1)$,
$\lim_{N\to\infty}N^{-1}\log\mathbb{E}Z_N^\theta=\Lambda(\theta)$.

\label{prop:A-guerra}
Let $\xi(t)=\sum_{p\ge2}\beta_p^2t^p$ have radius of convergence greater than one, and assume
that $\xi$ is convex on $[-1,1]$. Then for every $N\ge1$, every $\theta\in(0,1)$ and every
$\zeta\in\mathcal{P}([0,1])$ with $\zeta(\{0\})\ge\theta$,
\begin{equation}\label{eq:A-guerra}
 \frac1{N\theta}\log\mathbb{E}Z_N^\theta\le P_\zeta .
\end{equation}
Consequently $N^{-1}\log\mathbb{E}Z_N^\theta\le\Lambda(\theta)$ for every $N\ge1$ and
$\theta\in(0,1)$.

\label{lem:A-derivative}
In the setting above, $\varphi$ is continuous on $[0,1]$ and differentiable on $(0,1)$. For
every $u\in(0,1)$ there are probability measures $\mu_{u,0},\dots,\mu_{u,L}$ on
$\{-1,1\}^N\times\{-1,1\}^N$ such that
\begin{equation}\label{eq:A-derivative}
 \varphi'(u)=-\frac12\sum_{j=1}^Ly_j\bigl\{\psi(q_j)-\psi(q_{j-1})\bigr\}
 -\frac12\sum_{l=0}^L(y_{l+1}-y_l)\sum_{\sigma,\tau}\mu_{u,l}(\sigma,\tau)\,
 \Delta_l\bigl(R(\sigma,\tau)\bigr),
\end{equation}
where $R(\sigma,\tau)=N^{-1}\sigma\cdot\tau$ and
$\Delta_l(r)=\xi(r)-\xi(q_l)-\xi'(q_l)(r-q_l)$.

\label{cor:dict-field}
Let $\xi(t)=\beta^2t^2/2$ with $\beta>1$, let $T=1/\beta$, $h=\beta H$ and $f(H)$ be as in
\eqref{eq:B-field}, and let $\dot q(0)=1/\rho_\beta(0)$ with $\rho_\beta(0)$ as in Theorem~\ref{thm:sk}. Then, as
$H\to0$,
\begin{align}
 q_{\min}(\beta H)&=\Bigl(\frac{3T\dot q(0)}2\Bigr)^{1/3}|H|^{2/3}\,(1+o(1)),\label{eq:fld-pr-b4}\\
 f(H)&=f(0)-\frac{H^2}2+\frac3{20}\Bigl(\frac9{4T\dot q(0)}\Bigr)^{1/3}|H|^{10/3}\,(1+o(1)).
 \label{eq:fld-pr-b5}
\end{align}
These are the leading terms of (B4) and (B5) of \cite{PR09}.

\label{lem:dat-class-bounds}
Let $0<\varepsilon\le\frac14$, $\xi\in\mathcal{K}(\varepsilon)$, $a=\xi''$ and $\tau=a_0-1$. Then:
\begin{steplist}
\item $0<\tau<\varepsilon$, and $1<a_0\le a(t)\le1+\varepsilon$ for $t\in[0,1]$;
\item $0\le a'(t)\le\varepsilon t$, $0\le a''(t)\le\varepsilon$ and
 $0\le a(t)-a_0\le\varepsilon t^2/2$ for $t\in[0,1]$;
\item $0\le\xi^{(5)}(t)\le\varepsilon$ and $0\le a'(t)-\xi''''(0)t\le\varepsilon t^2/2$ for
 $t\in[0,\frac12]$;
\item the functions $\ell(q)=\int_0^1a(sq)\,ds$ and $\chi(q)=\int_0^1v\,\xi'''(vq)\,dv$
 satisfy $\xi'(q)=q\ell(q)$ and $\xi''(q)=\ell(q)+q\chi(q)$ on $[0,1]$, $\ell(0)=a_0$,
 $\ell'(0)=0$, $\chi(0)=0$, $\chi'(0)=\xi''''(0)/3$, $\chi\ge0$, $1<\ell\le1+\varepsilon$, and
 $|\ell'|,|\ell''|,|\chi|,|\chi'|,|\chi''|\le\varepsilon$ on $[0,\frac12]$.
\end{steplist}

\label{lem:dat-branch}
There is an absolute constant $\overline C\ge1$ such that, for every $\xi\in\mathcal{K}(\frac14)$, all
partial derivatives of $\Upsilon$ and $\varpi$ in $(q,\theta)$ of orders one and two are
bounded by $\overline C$ on $[0,\frac14]\times[0,1]$. For $0<q\le\frac14$,
\begin{align}
 \frac{\mathfrak{T}(\xi'(q),\theta)}q-1&=\Upsilon(q,\theta),\label{eq:C-rs-identity}\\
 \xi''(q)\,\mathfrak{S}(\xi'(q),\theta)-\frac{\mathfrak{T}(\xi'(q),\theta)}q
 &=q\,\varpi(q,\theta).\label{eq:C-at-identity}
\end{align}
At $q=0$,
\begin{equation}\label{eq:C-zero-jets}
\begin{gathered}
 \Upsilon(0,\theta)=\tau,\qquad
 \partial_q\Upsilon(0,\theta)=-a_0^2(2-\theta),\qquad
 \partial_\theta\Upsilon(0,\theta)=0,\\
 \varpi(0,\theta)=-a_0^2\theta,\qquad
 \partial_\theta\varpi(0,\theta)=-a_0^2,\qquad
 \partial_q\varpi(0,\theta)=a_0^3\bigl(\tfrac43+3\theta-\theta^2\bigr)+\tfrac13\xi''''(0) .
\end{gathered}
\end{equation}

\label{lem:D-plateau}
For all small $\theta>0$ and every even $H$ with $\|H\|_{10}\le1$,
\begin{equation}\label{eq:D-plateau}
 \bigl|\nu^\theta_q(H)-\nu^*_q(H)-H''(0)\,\Pi_\theta-\gamma_\theta\,q\,H''''(0)\,I_\theta\bigr|
 \le C\bigl(\theta^5+\theta^3L_\theta\bigr).
\end{equation}
Moreover $|\Pi_\theta-a_0^2U^\theta(0,0)\,I_\theta|\le C\theta^4$.
